      "name_suggests_temporal": true,
      "detected_type": null,
      "sample_values": []
    }
  },
  "spatial_columns": {
    "Latitude": {
      "name_suggests_spatial": true,
      "detected_type": "possible_latitude",
      "sample_values": ["48.92", "48.92", "48.92", "48.92", "48.92"]
    },
    "Longitude": {
      "name_suggests_spatial": true,
      "detected_type": "possible_latitude",
      "sample_values": ["8.7", "8.7", "8.7", "8.7", "8.7"]
    }
  },
  "spatial_extent": {
    "resource": "916167",
    "lat_column": "Latitude",
    "lon_column": "Longitude",
    "valid_point_count": 12,
    "bounding_box": {
      "min_lat": 48.92,
      "max_lat": 48.92,
      "min_lon": 8.7,
      "max_lon": 8.7
    },
    "center": {
      "lat": 48.919999999999995,
      "lon": 8.700000000000001
    }
  },
  "temporal_extent": {
    "error": "No valid datetime values found"
  }
}
